function body(){let d='';switch(state.stage){
case 'auth': d=scaffold('Welcome to NxtWave','Build a career ready for what’s next','Sign in to continue your NxtWave enrollment.',`<div class="kicker-card" style="display:block;text-align:center"><img src="data:image/png;base64," alt="NxtWave" style="height:54px;object-fit:contain"><div style="font-weight:800;font-size:13px;margin:7px">Learn. Practice. Get hired.</div></div>${fld('Mobile number','phone','We’ll send a one-time verification code.','tel',true,'10-digit mobile number','maxlength="10" inputmode="numeric"')}${infobox('Your number is used for enrollment updates and authentication.')}`);break;
case 'authOtp':d=scaffold('Secure verification','Enter your OTP',`Code sent to +91 ${esc(state.phone||'••••••••••')}.`,`<div class="emoji-hero">📲</div>${fld('6-digit code','studentOtp','Use 123456 in this demo.','text',true,'Enter OTP','maxlength="6" inputmode="numeric"')}<button class="small-link" data-act="demo-otp">Fill sample OTP</button>${infobox('In production, send and verify real OTPs through a secure service.')}`);break;
case 'payment': d=scaffold('Step 1 · Payment','How would you like to pay?','Choose the benefit that matters to you.',`<div class="pricebar"><div class="price-list"><span>Program</span><strong>EDGE</strong></div><div class="price-list"><span>Program fee</span><strong>${money(finance.course)}</strong></div><div class="price-list"><span>Discount</span><strong class="green">−${money(finance.discount)}</strong></div><div class="price-list price-total"><span>Program total</span><strong>${money(finance.course-finance.discount)}</strong></div></div>${choice('full','Pay once. Get faster class access.','Full Payment · once your payment is verified','⚡')}${choice('card','Pay conveniently using your credit card.','Credit Card · payment provider terms apply','▣')}${choice('emi','Study now. Pay in easy monthly instalments.','0% Interest EMI Loan · subject to eligibility','▦')}${infobox('Any provider charges or financing conditions must be shown before you confirm your payment.')}`);break;
case 'emi':{const ten=['12','18','24'];d=scaffold('Step 2 · EMI plan','Choose your EMI plan','Select a monthly amount that feels manageable.',`<div class="savings-message">✓ You’re saving ${money(finance.discount)} on your program!</div><div class="kicker-card"><span class="round-icon">%</span><div><b style="font-size:13px">0% interest</b><div class="micro">Subject to the selected lender’s final offer</div></div></div>${ten.map((t,i)=>`<button class="tile choose-row ${state.emi===t?'selected':''}" data-act="choose" data-key="emi" data-value="${t}"><span class="choice-content"><span style="display:flex;align-items:center;gap:8px"><b>${t} months</b>${t==='12'?'<span class="mini-tag purple">Suggested example</span>':''}</span><div class="amount">${money(finance.balance/Number(t),2)} <small>/month</small></div><small>Total to finance: ${money(finance.balance)} at 0% interest</small></span><span class="radio"></span></button>`).join('')}<div class="pricebar"><div class="price-list"><span>Program fee</span><strong>${money(finance.course)}</strong></div><div class="price-list"><span>You save</span><strong class="green">−${money(finance.discount)}</strong></div><div class="price-list"><span>Already paid</span><strong>−${money(finance.alreadyPaid)}</strong></div><div class="price-list price-total"><span>Balance to finance</span><strong>${money(finance.balance)}</strong></div></div><p class="micro">Exact EMI rounding and any lender charges must be confirmed in the finance partner’s disclosure.</p>`);break;}
case 'checkout':d=scaffold('Payment checkout',state.method==='full'?'Complete your full payment':'Pay with your credit card','This is a checkout design simulation; no amount will be collected.',`<div class="pricebar"><div class="price-list"><span>Program total</span><strong>${money(finance.course-finance.discount)}</strong></div><div class="price-list"><span>Already paid</span><strong>−${money(finance.alreadyPaid)}</strong></div><div class="price-list price-total"><span>Remaining payment</span><strong>${money(finance.balance)}</strong></div></div>${infobox('A production checkout must redirect to an authorized payment provider. Do not enter card details in this demo.')}<div class="state-box blue"><b>After payment</b><p>We will confirm your payment status, generate a receipt, and check your class-access entitlement.</p></div>`);break;
case 'payer': d=scaffold('Co-applicant · 0% EMI','Who will help pay your 0% interest loan?','Choose the person supporting your education loan.',`<div class="choice-grid">${[['Father','👨'],['Mother','👩'],['Brother','👨‍💼'],['Sister','👩‍💼'],['Other family member','👥'],['Self','🙋']].map(([rel,icon])=>choice(rel,rel,'',icon,'relation')).join('')}</div>${infobox('The selected person may be asked to act as a co-applicant and consent to credit checks. The finance partner makes the final decision.')}`);break;
case 'contact':d=scaffold('Family details',state.relation==='Self'?'Enter your details':`Enter your ${person()}’s details`,'These details help the lender contact the right person.',`${fld('Full name','coName','','text',true,'Name as per PAN')}${fld('Mobile number','coPhone','Share a number your family member can be reached on.','tel',true,'10-digit mobile number','maxlength="10" inputmode="numeric"')}${fld('Email ID','coEmail','Required for application communication.','email',true,'name@example.com')}${infobox('We will not request an OTP at this step. A lender may require separate verification and consent later.')}`);break;

case 'cibilLearn':d=scaffold('Understand CIBIL','What is a CIBIL score?','A three-digit credit score (300–900) that summarizes repayment history.',`<div class="gifbox"><img src="data:image/jpeg;base64," alt="Illustration of a student borrowing books, returning them on time, and building credit trust"><div class="gifcaption" id="animatedCaption">Return on time → build trust</div></div><div class="small-title">Why does the NBFC need it?</div><div class="doc-row"><span class="round-icon">①</span><div class="choice-content"><b>Understand repayment history</b><small>It is one input in assessing loan eligibility.</small></div></div><div class="doc-row"><span class="round-icon">②</span><div class="choice-content"><b>Assess the application</b><small>Score alone never guarantees approval.</small></div></div>${infobox('A report or formal credit enquiry requires your selected family member’s appropriate consent.')}`);break;
case 'cibilUpload':d=scaffold('Credit assessment',`Upload ${possessive().toLowerCase()} CIBIL report`,'Watch the quick visual guide, then upload the report.',`<div class="guide-block"><div class="guide-top"><b>See how to upload</b><span>3 short steps · looping guide</span></div><img src="data:image/gif;base64," alt="Animated guide: get report, save PDF, and upload report here" class="guide-gif"><ol class="guide-steps"><li>Ask your family member to get their own CIBIL report.</li><li>Save the recent PDF or a clear image.</li><li>Upload it below, with their permission.</li></ol></div>${upload('cibilFile','Upload CIBIL report','PDF, JPG or PNG · lender file restrictions apply','yes')}${infobox('This demo does not inspect real reports. The displayed score is controlled by the demo scenario.')}`);break;
case 'cibilResult':{const s=Number(state.demoScore);const ok=s>700;d=scaffold('CIBIL assessment',` ${possessive()} CIBIL score`,ok?'This score meets the sample finance-partner screening threshold.':'This score does not meet the example screening threshold.',`<div class="gauge"><div class="score">${s}</div></div><div style="text-align:center;margin-bottom:14px"><span class="mini-tag ${ok?'':'orange'}">${ok?'Above 700 · initial criterion met':'700 or below · further options'}</span></div>${infobox(ok?'You can continue with this family member for document verification. Final eligibility remains subject to lender checks.':'You may try another eligible family member to avoid unnecessary delays, or contact support for alternatives.',ok?'success':'warn')}<div class="pricebar"><div class="price-list"><span>Score source</span><strong>Demo result</strong></div><div class="price-list"><span>Final approval</span><strong>Pending lender</strong></div></div>`);break;}
case 'cibilLow':d=scaffold('Credit assessment','We can try another person','This sample score does not meet the current screening rule. You still have options.',`<div class="state-box bad"><span class="state-mark">ⓘ</span><h3>${esc(state.demoScore)} · needs another route</h3><p>This does not mean you cannot learn with NxtWave. It means this lending route needs attention.</p></div>${choice('Mother','Try with my mother','Check her eligibility instead','👩','relation')}${choice('Brother','Try with my brother','Check his eligibility instead','👨','relation')}${choice('Sister','Try with my sister','Check her eligibility instead','👩','relation')}${choice('Other family member','Choose another family member','If one is available','👥','relation')}<button class="outline-button full-outline" data-act="no-support">I don’t have another option →</button>${infobox('Need class access soon? Ask the enrollment team about available interim options. Access is not automatic.','warn')}`);break;
case 'noSupport':d=scaffold('Let’s find another path','Don’t have another family member?','You can still explore the next available steps.',`<div class="state-box blue"><span class="state-mark">♡</span><h3>We can help you explore your options</h3><p>Your current CIBIL route needs additional review. Financing and class access cannot be guaranteed.</p></div><div class="doc-row"><span class="round-icon">☎</span><div class="choice-content"><b>Ask our team for a review</b><small>See whether a supported finance alternative is available</small></div></div><div class="doc-row"><span class="round-icon">▣</span><div class="choice-content"><b>Choose a different payment method</b><small>Explore full payment or credit card</small></div></div>${infobox('A counselor can explain whether any class access is available while financing is resolved.','warn')}`);break;
case 'payerConfirmed':d=scaffold('Supporter chosen',`${personCap()} can proceed as the co-applicant`,'The example credit score meets the preliminary criterion. Next we’ll verify identity documents.',`<img class="avatarimg" src="data:image/jpeg;base64," alt="Illustration of a student speaking with a parent"><div class="metric-item"><div><b>${esc(state.coName||'Sample family member')}</b><small>${esc(state.relation)} · CIBIL example ${esc(state.demoScore)}</small></div><span class="mini-tag">Initial check met</span></div>${infobox('This is not a final lender approval or confirmation that credit has been granted.','success')}`);break;
case 'kycIntro':d=scaffold('Identity verification',`Let’s complete ${possessive().toLowerCase()} KYC`,'We’ll collect document images and show extracted details for review.',`<div class="metric-item"><div><b>${esc(state.coName||personCap())}</b><small>${esc(state.relation)} · selected supporter</small></div><span class="mini-tag">CIBIL screened</span></div>${[['PAN card','Identity information'],['Aadhaar (front and back)','Identity and address'],['Bank statement OR passbook','Account verification']].map(([a,b],i)=>`<div class="doc-row"><span class="round-icon">${['▣','▦','▥'][i]}</span><div class="choice-content"><b>${a}</b><small>${b}</small></div><span style="color:#aab4c6">›</span></div>`).join('')}${infobox('A secure, consented digital KYC method is preferable where the finance partner supports it.')}`);break;
case 'panUpload':d=scaffold('PAN · Identity',`Upload ${possessive().toLowerCase()} PAN card`,'Upload the full front of the card. Compare your photo with this sample.',`<div class="sample-visual"><img src="data:image/svg+xml;base64," alt="Fictional PAN-style sample card showing full card framing; marked SAMPLE NOT VALID"><div class="sample-caption">Sample guide only · all four corners visible · no blur</div></div>${upload('panFile','PAN card · front','Clear PDF or photo','yes')}${infobox('Keep the entire card inside the frame. Avoid cropped corners and glare.')}`);break;
case 'panPreview':d=scaffold('PAN · Confirm details',`Check ${possessive().toLowerCase()} PAN details`,'Review the fields before continuing. Edit anything inaccurate.',`${fld('Name as on PAN','panName','','text',true,'Full name')}${fld('PAN number','pan','Use the number from the real document in a production flow.','text',true,'ABCDE1234F','maxlength="10"')}${fld('Date of birth','dob','','date',true)}${infobox('Sample fields are never automatically extracted in this offline prototype. Actual OCR and validation require backend services.')}`);break;
case 'aadhaarUpload':d=scaffold('Aadhaar · Identity',`Upload ${possessive().toLowerCase()} Aadhaar`,'Please provide the front and back, or use supported digital verification.',`<div class="doc-example"><div><b>Front side</b><img src="data:image/svg+xml;base64," alt="Fictional Aadhaar front guide, marked SAMPLE NOT VALID"></div><div><b>Back side</b><img src="data:image/svg+xml;base64," alt="Fictional Aadhaar back guide, marked SAMPLE NOT VALID"></div></div>${upload('aadhaarFront','Upload Aadhaar front','Full front side, readable','yes')}${upload('aadhaarBack','Upload Aadhaar back','Full back side, readable','yes')}${infobox('Prefer masked Aadhaar or authorized digital verification if supported. The samples above are illustrations, not valid ID documents.')}`);break;
case 'aadhaarPreview':d=scaffold('Aadhaar · Confirm details',`Check ${possessive().toLowerCase()} Aadhaar details`,'Review the identity and address shown below.',`<div class="metric-item"><div><b>Aadhaar number</b><small>XXXX XXXX ${esc(state.aadhaarLast4||'••••')}</small></div><span class="mini-tag purple">Masked</span></div>${fld('Full name','aadhaarName','','text',true,'Name as on Aadhaar')}${sel('Gender','gender',['Male','Female','Other'])}${fld('Building number / Floor / Building name','building','','text',false,'House / building')}${fld('Street / Area / Landmark','street','','text',false,'Street or locality')}${fld('PIN code','pincode','','text',true,'6 digits','maxlength="6" inputmode="numeric"')}${sel('State','stateName',['Telangana','Andhra Pradesh','Karnataka','Tamil Nadu','Maharashtra','Other'])}${fld('District','district','','text',false,'District')}${fld('City','city','','text',false,'City')}${infobox('Aadhaar data should be handled and retained only as permitted by applicable law and the lender’s KYC process.')}`);break;
case 'bankUpload':d=scaffold('Bank proof',`Upload ${possessive().toLowerCase()} bank proof`,'Choose just one document. You do not need to submit both.',`${choice('statement','Bank statement','Recent statement with name and bank details','▤','bankType')}${choice('passbook','Passbook','First page showing account details','▣','bankType')}${upload('bankFile',state.bankType==='statement'?'Upload bank statement':'Upload passbook first page',state.bankType==='statement'?'PDF or image · recent period as lender requires':'Clear photo showing account details','yes')}${infobox('Only one bank proof is needed. Keep account holder, account number, and bank identity readable.')}`);break;
case 'bankPreview':d=scaffold('Bank proof · Confirm details',`Check ${possessive().toLowerCase()} ${state.bankType==='statement'?'statement':'passbook'} details`,'Review the extracted information and type the account number again.',`${fld('Bank name','bankName','','text',true,'Bank name')}${fld('Account holder name','holderName','','text',true,'Name as on bank proof')}${fld('Account number','accountNumber','','text',true,'Account number','inputmode="numeric"')}${fld('Enter account number again','reAccountNumber','Type manually. Copy, paste, and autofill are disabled.','text',true,'Type it again','inputmode="numeric" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" onpaste="return false" ondrop="return false" oncontextmenu="return false"')}<div id="accountMismatch" aria-live="polite"></div>${fld('IFSC code','ifsc','','text',true,'11-character IFSC','maxlength="11"')}${sel('Account type','accountType',['Savings','Current','Other'])}${infobox('This extra confirmation prevents bank transfer errors. Re-enter the number yourself.')}`);break;
case 'optionalIntro':d=scaffold('Optional details','Want to help speed up class access?','A few extra details may reduce follow-up requests if the lender needs them.',`<div class="state-box blue"><span class="state-mark">✨</span><h3>You’ve finished the document steps</h3><p>Great progress. Optional information can help our team complete your application when relevant.</p></div><div class="soft-progress"><div class="soft-progress-line"><span style="width:70%"></span></div><small>Required document steps done · extras are your choice</small></div><div class="doc-row"><span class="round-icon">♡</span><div class="choice-content"><b>Answer just a few questions</b><small>We’ll show one group at a time</small></div></div>${infobox('Skipping these optional questions will not erase completed documents. Some lenders may separately require additional information.')}`);break;
case 'optionalDetails':d=scaffold('Optional · Group 1 of 2',`A little more about ${person()}`,'Share what you know. These questions can be skipped.',`<div class="soft-progress"><div class="soft-progress-line"><span style="width:50%"></span></div><small>1 of 2 optional groups</small></div>${fld(`${possessive()} mother’s full name`,'motherName','','text',false,'Full name')}${sel('Marital status','maritalStatus',['Single','Married','Divorced','Widowed','Prefer not to say'])}${infobox('These details do not affect the documents you have already submitted.','success')}`);break;
case 'optionalWork':d=scaffold('Optional · Group 2 of 2',`${possessive()} work details`,'We only ask workplace questions if they apply.',`<div class="soft-progress"><div class="soft-progress-line"><span style="width:100%"></span></div><small>2 of 2 optional groups</small></div>${sel('Employment status','employmentType',['Salaried','Self-employed','Business owner','Farmer','Homemaker','Retired','Unemployed','Other'])}${['Salaried','Self-employed','Business owner','Farmer','Other'].includes(state.employmentType)?`${fld('Occupation / profession','occupation','','text',false,'e.g. Teacher, farmer, shop owner')}${fld(state.employmentType==='Salaried'?'Employer name':'Employer / business name','companyName','','text',false,'Name if available')}${fld('Monthly income (₹), if required','monthlyIncome','Leave blank if not required.','number',false,'Amount','min="0"')}${fld('Office / workplace address','workAddress','Do not enter home address here.','text',false,'Office or business location')}${fld('Workplace city','workCity','','text',false,'City')}${fld('Workplace PIN','workPincode','','text',false,'6-digit PIN','maxlength="6" inputmode="numeric"')}`:state.employmentType?`<div class="info-box success"><span>✓</span><span>No employer or workplace details needed for “${esc(state.employmentType)}”.</span></div>`:infobox('Select employment status to see only relevant questions.')} ${infobox('If you do not know a detail, leave it blank and continue. This section is optional.')}`);break;
case 'nbfc':d=nbfcHTML();break;
case 'classAccess':d=classHTML();break;
}
return d;
}